package com.example.demo.adapters.jdbc;

import com.example.demo.application.commands.ReceiveMessageCommand;
import com.example.demo.domain.Message;
import com.example.demo.domain.TimeOrderedUuid;
import com.example.demo.domain.events.MessageReceivedEvent;
import com.example.demo.jobs.JdbcReceiveMessageOutbox;
import java.time.Instant;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

@Repository
public class JdbcReceiveMessageCommand implements ReceiveMessageCommand {

    private final JdbcClient jdbc;
    private final JdbcReceiveMessageOutbox outbox;

    public JdbcReceiveMessageCommand(JdbcClient jdbc, JdbcReceiveMessageOutbox outbox) {
        this.jdbc = jdbc;
        this.outbox = outbox;
    }

    @Override
    @Transactional
    public Message execute(ReceiveMessageCommand.Input input) {
        JdbcClient.StatementSpec statement = jdbc.sql("insert into messages (id, body) values (:id, :body) returning id, body, created_at");
        statement = statement.param("id", input.id());
        statement = statement.param("body", input.body());
        var result = statement.query(Message.class).single();
        outbox.stage(new MessageReceivedEvent(TimeOrderedUuid.next(), TimeOrderedUuid.next(), Instant.now()));
        return result;
    }
}
